from _lib import *

M15 = module("M15", "Mathematics 15: statistics - reading evidence without being fooled", "Mathematics",
  "A number on its own lies. Statistics is how you turn a pile of numbers into an honest story - the middle, the spread, the picture - and how you catch the tricks people use to make numbers say what they want. Every model, every experiment, every headline rests on this.",
  "Abid", "A one-page honest summary she makes of her own school data (minutes, programs, streak over time): the real average, the spread, and the one chart that does not mislead.",
  [
    lesson("M15-L1", "The middle: mean, median, mode, and when each one lies",
      ["Compute mean, median and mode of a small data set and say what each means", "Show a case where the mean misleads (one huge value) and the median is honest", "Choose the right 'middle' for a real question"],
      FROM_ZERO + "Three middles. Mean (add, divide), median (the middle one when sorted), mode (the most common). The trap: incomes of five people where one is a millionaire - the mean says everyone is rich, the median tells the truth. She computes all three for her own session minutes. Rule: the mean is fooled by outliers; the median is not. Check: which middle for 'typical house price' and why."),
    practice("M15-P1", "Practice: the middle", ["mean-median-mode", "outliers-and-mean", "choose-the-middle"]),
    lesson("M15-L2", "The spread: range, and why two groups with the same average differ",
      ["Compute the range and explain spread in words (how much the numbers vary)", "Show two sets with the same mean but different spread and why spread matters", "Meet standard deviation as 'typical distance from the middle' (concept, not the full formula)"],
      FROM_ZERO + "Two classes average 60, but one is all 58-62 and one is 20-100 - the average hides everything. Range (biggest minus smallest). Spread as the real story; standard deviation introduced as 'the typical distance from the mean' - she computes it once by hand for five numbers to feel it, no memorising the formula. Security tie: a server's average response time looks fine while one request in a thousand hangs - the spread is where the bug hides. Check: why same mean can mean different things."),
    code("M15-CODE1", "Code: Python summarises a real data set honestly",
      ["Compute mean, median and spread of a list with Python (statistics module)", "Draw a simple histogram and read its shape", "Run it on her own school numbers and say what is true"],
      "import statistics\n\nminutes = [40, 55, 98, 109, 43, 0, 120, 60, 50, 54]\nprint(\"mean:\", statistics.mean(minutes))\nprint(\"median:\", statistics.median(minutes))\nprint(\"range:\", max(minutes) - min(minutes))\nprint(\"stdev:\", round(statistics.pstdev(minutes), 1))\n",
      "She runs it on real numbers (her own minutes, or data the tutor gives). Then a text histogram (buckets, stars) and, in her terminal, matplotlib for a real one. The gift: her honest one-pager. The lesson: the median of her minutes tells a truer story than the mean when a zero-day sits in the list. Save."),
    lesson("M15-L3", "How charts lie: the five tricks, and how to catch them",
      ["Spot a truncated y-axis, a cherry-picked range, a misleading scale, a correlation sold as cause, and a missing base", "Redraw one misleading chart honestly", "State the questions that catch each trick (out of how many, compared to what, since when, does A cause B)"],
      FROM_ZERO + "The module M10 touched this; now it is a skill. Five tricks with real-shaped examples: the y-axis not starting at zero (a tiny change looks huge); a range chosen to show a trend that reverses if you zoom out; correlation dressed as cause (ice cream and drowning both rise in summer); the missing denominator (base rates again, M14). She fixes one chart. The catching questions on a card. Check: name two tricks and the question that catches each."),
    lesson("M15-H1", "Horizon: statistics behind models, medicine and the news she reads",
      ["Explain how an experiment tests a claim (a control group, a sample, 'significant' in one line)", "Explain how every AI model is evaluated with statistics (accuracy on data it has not seen - her Companion, LV2)", "Ask: given a scary headline number, what three questions does she ask before believing it"],
      HORIZON + "How knowledge is made honest: a control group, a big enough sample, and 'statistically significant' meaning 'unlikely to be chance' (M14). How her own field judges models: test on data the model never saw (why a model that memorised looks great and fails in the world - LV2). The news: the three questions (out of how many, compared to what, who paid for the study). Boundary Question: 'A headline says a food doubles a risk. What do you need to know before you change what you eat?'"),
    check("M15-C", "Mathematics 15 checkpoint", ["mean-median-mode", "spread-and-stdev", "read-a-histogram", "charts-that-lie"], count=12),
    teach("M15-T", "Explain to a younger student why the average can lie and the median can be more honest, with one example. Then say one way a chart can trick you and how to catch it. Say it out loud first, then write it. 4-6 sentences."),
  ])

SS5 = module("SS5", "Systems & Society 5: companies and incentives - why organisations do what they do", "Systems & Society",
  "A company is a machine for turning work into money, and it mostly does whatever its incentives reward - not what anyone intends. Learn to read incentives and you can predict an organisation's behaviour, see why good people in bad systems do bad things, and understand the business behind every app on your phone.",
  "Abid", "A clear map she draws for Abid of how a free app she uses actually makes money, and who the real customer is.",
  [
    lesson("SS5-L1", "What a company is, and the one question that explains its behaviour",
      ["Define a company, profit, and the difference between revenue and profit", "Explain incentives as the real steering wheel ('show me the incentive and I'll show you the outcome')", "Predict a simple behaviour from an incentive before being told"],
      FROM_ZERO + "A company takes in money (revenue), spends some (costs), keeps the rest (profit). But what it DOES is set by incentives - what it is rewarded for. The famous line, applied: a support team rewarded for closing tickets fast will close them unsolved. She predicts three behaviours from three incentives. Mechanism, not cynicism. Check: revenue vs profit; one behaviour from an incentive."),
    lesson("SS5-L2", "If it's free, you're the product: the attention business",
      ["Trace how a free app makes money (ads, data, a cut, a subscription upsell) and name the real customer", "Explain why 'engagement' is the incentive and what it rewards (whatever keeps you scrolling)", "Connect to her own privacy choices (the Companion offline, AI1; her data, DEF1/SS3)"],
      FROM_ZERO + "The gift's core. A free app's bills get paid somehow - usually advertisers pay for her attention, so SHE is what is sold and the advertiser is the customer. 'Engagement' as the measured incentive, and what maximising it rewards (outrage, endless feeds) - mechanism, no moralising. She maps one app she uses. Her own counter-choices now have a reason: offline AI, minimal data, reading the terms (SS3). Check: who the real customer of a free app is."),
    lesson("SS5-L3", "When incentives go wrong: externalities, short-termism, and the role of rules",
      ["Explain an externality (a cost pushed onto others - pollution, a data leak's victims)", "Explain why a company may do harm without anyone intending it (the incentive did)", "Explain why rules, audits and liability exist (SS1's checks, applied to companies)"],
      FROM_ZERO + "An externality: a cost that lands on people outside the deal - a factory's smoke, a breached company's leaked users (DEF1). Short-termism: rewarded for this quarter, a company skips the security work that pays off in three years (why breaches happen - the incentive, not evil). The fix is the same shape as SS1: outside checks - regulators, audits, laws that make the company pay for the harm (liability) so the cost comes back inside. Check: one externality; why a rule can change behaviour an appeal to goodness cannot."),
    lesson("SS5-H1", "Horizon: big tech, monopolies and the incentives behind the internet she lives on",
      ["Explain network effects and why some tech companies become huge (the value is the other users)", "Explain the incentive behind data collection and 'lock-in' as mechanism, no villains", "Ask who benefits, how would you break it, how would you fix it - for a platform that holds everyone's photos"],
      HORIZON + "Why a few companies run so much of the internet: network effects (a chat app is worth using because everyone is on it - the value is the users, so the winner takes most) and lock-in (hard to leave because your photos and friends are inside). The incentive to collect data follows from the attention business (L2). Mechanism, examples plural, no company cast as hero or villain. Her tools (open source, her own Pi, her own domain coming at L8) are the escape hatch - and she now knows why. Boundary Question: 'A platform holds a billion people's photos. What does it gain by keeping them a little hard to export, and what rule would fix that?'"),
    check("SS5-C", "Systems & Society 5 checkpoint", ["company-and-profit", "incentives-predict-behaviour", "attention-business", "externalities-and-rules"], count=10),
    teach("SS5-T", "Explain to a 10-year-old why a free app still needs to make money and how it does, and who the real customer is. Then explain what an incentive is with one example. Say it out loud first, then write it. 5-7 sentences."),
  ])

CS7 = module("CS7", "Computing 7: the operating system from the inside - processes, memory, isolation", "Computing",
  "You have used an operating system, defended one, and served from one. Now you look inside the thing itself: how it runs many programs at once on one chip, gives each its own private memory, and stops any one of them from touching another. The isolation you have trusted all along - here is how it actually works.",
  "Abid", "A short, clear explanation she writes for Abid of what really happens in the one second between clicking an app and seeing it open - the scheduler, the memory, the isolation - with a drawing.",
  [
    lesson("CS7-L1", "Doing many things at once on one chip: the scheduler",
      ["Explain that a single core runs one thing at a time and the OS switches fast (time-slicing), with the numbers", "Watch context switches and load with top/vmstat and explain what 'load average' means", "Explain a thread vs a process in one line each"],
      FROM_ZERO + LINUX + "Her laptop 'runs' fifty programs on a few cores by switching between them thousands of times a second - each gets a slice (CS3's processes, now the mechanism). top shows it; the load average is how many want to run at once. Thread (a strand of work inside a process, sharing its memory) vs process (its own memory). She reasons about why too many hungry programs make everything slow. Check: time-slicing in her words; thread vs process."),
    lesson("CS7-L2", "Every program thinks it owns the memory: virtual memory and the great trick",
      ["Explain virtual memory (each process sees its own clean address space; the OS maps it to real RAM)", "Explain why this is the isolation she has trusted since CS3 (a process literally cannot name another's memory)", "Explain paging and swap in one line each, and see them"],
      FROM_ZERO + LINUX + "The deep one, back to CS1B-L0. Each process sees addresses starting at zero as if it owned all memory - but those are VIRTUAL; the OS and the chip translate them to scattered real RAM, and a process's address 1000 and another's address 1000 are different real places. THAT is why one program cannot read another's secrets - it cannot even name them (DEF1's isolation, now the mechanism). Paging (memory in blocks), swap (spilling to disk when RAM is full - she sees it in free -h). Check: why virtual memory is the isolation, in her words."),
    lesson("CS7-L3", "The kernel and the wall: user mode, kernel mode, and system calls",
      ["Explain the two modes (programs run restricted; only the kernel touches hardware) and why", "Explain a system call as the guarded door between them, and watch real ones with strace", "Connect to least privilege (CS3/DEF1): the ultimate privilege boundary is in the chip itself"],
      FROM_ZERO + LINUX + "Why can't a program just grab the disk or the network? Because it runs in USER mode, where those are forbidden; only the KERNEL runs in privileged mode. To do anything real - open a file, send a packet - a program asks the kernel through a SYSTEM CALL, a guarded door that checks permission (CS3-L2, now enforced by hardware). strace ls shows the actual calls (openat, read, write) - she reads a few. The whole security model rests here: the wall is in the silicon. Check: user vs kernel mode; what a system call is."),
    lesson("CS7-H1", "Horizon: containers, VMs, and how the cloud runs everyone safely on one machine",
      ["Explain a virtual machine (a whole fake computer) and a container (an isolated process) and the trade-off", "Explain how a cloud provider runs a thousand customers on one machine without them seeing each other (the isolation, scaled)", "Explain, as a phenomenon, that isolation sometimes breaks (a bug lets one escape) and why that is the most serious kind"],
      HORIZON + "How Vercel and Neon run the school next to a thousand strangers safely: isolation, scaled. A VM (a whole emulated computer, strong wall, heavier); a container (an isolated process sharing the kernel, lighter - what most of the cloud uses). The school itself runs this way. The serious failure named, not taught: a bug that lets code escape its container or VM onto the host or a neighbour - the highest-value, hardest kind, which is why cloud security teams exist. Boundary Question: 'You rent one machine shared with strangers. What is the one thing that, if it broke, would expose everyone - and who works to prevent it?'"),
    check("CS7-C", "Computing 7 checkpoint", ["scheduler-time-slicing", "virtual-memory-isolation", "user-vs-kernel", "system-calls"], count=10),
    teach("CS7-T", "Explain to Abid how one laptop runs many programs at once and why one program cannot read another's memory, using the words slice, virtual memory and kernel. Say it out loud first, then write it. 5-7 sentences."),
  ])

CS8 = module("CS8", "Computing 8: C and the machine - pointers, memory, and why safe languages exist", "Computing",
  "Python protected you from the machine. C takes the padding away: you hold memory addresses in your hand, and you see exactly why a single mistake can let an attacker in. You will write a small overflow and then FIX it, in a sandbox you own, so that for the rest of your life you understand - in your bones - why memory safety matters.",
  "Abid", "A one-page 'why some bugs are dangerous and others are not' she writes for Abid, with the memory drawing that makes it obvious.",
  [
    lesson("CS8-L1", "Closer to the metal: compiling, types that are sizes, and the first C program",
      ["Explain compiling (C becomes machine code before it runs, unlike Python) and write/compile hello.c with gcc", "Explain that a C type is a size in bytes and why that matters (back to CS1B-L0)", "Explain the trade: C is fast and exact, and gives you no safety net"],
      FROM_ZERO + LINUX + LAB + "In a VM or a plain folder she owns. C is compiled: gcc hello.c -o hello turns it into machine code (CS1's instructions) before it runs - that is why it is fast and why errors show up differently. A type is a SIZE: an int is 4 bytes, a char is 1 - she prints sizeof. The honest trade: speed and control, no guard rails. Check: compiled vs interpreted; what sizeof tells her."),
    lesson("CS8-L2", "Pointers: a variable that holds an address",
      ["Explain a pointer as a box holding the address of another box (the mailbox and its number), with a drawing", "Print a real memory address with %p and follow a pointer to its value", "Explain why pointers are powerful and dangerous (you can point at the wrong place)"],
      FROM_ZERO + LINUX + LAB + "The idea that scares people and should not. A pointer holds an ADDRESS (CS1B-L0's addresses, finally in her hands). int x = 5; int *p = &x; - p holds where x lives; *p reads it. printf %p prints the actual address - she sees real memory. Draw the mailbox. Power: change a thing from afar, build big structures. Danger: point at an address you shouldn't, and the machine lets you - no net. Check: what a pointer holds; what & and * do."),
    lesson("CS8-L3", "The overflow, made and fixed - why bounds checks exist forever",
      ["Explain a buffer as a fixed row of boxes and what happens when you write past the end (into the neighbour)", "In her own sandbox, write a tiny program that overruns a small buffer and observe the corruption; then FIX it with a bounds check", "Explain why memory-safe languages (Python, Rust) were invented and what they do automatically"],
      FROM_ZERO + LINUX + LAB + "The lesson the whole security world turns on, done safely on her own machine only (she states the lab rule). A buffer is a fixed array; C does not check if she writes past it - so char buf[4]; and copying 8 characters writes into whatever sits next in memory (CS6's contiguous boxes; CS7's layout). She writes a tiny program that overruns a buffer and sees a value next door change or the program crash - the mechanism of the most famous bug class, observed, not weaponised (no exploit, no shellcode - just 'past the end corrupts the neighbour'). Then she FIXES it: check the length before copying (strncpy/bounds). The payoff: Python and Rust do this check for her automatically - now she knows what they are protecting her from and why they exist. Boundary Question: 'Where does the extra data go when you write past a buffer, and what is the defender's one rule?' (check the length first). Check: what overflowing a buffer does; why safe languages were invented."),
    lesson("CS8-H1", "Horizon: memory bugs in the real world, and the slow victory of safe languages",
      ["Explain that a large share of serious real-world vulnerabilities have been memory bugs for decades, and why C's speed kept it everywhere", "Explain the industry's shift to memory-safe languages (Rust in operating systems, Android, browsers) as the defender's structural fix", "Ask who benefits, how would you break it, how would you fix it - at the language level"],
      HORIZON + "For decades, a large fraction of the worst vulnerabilities in operating systems and browsers were memory bugs of exactly the shape she just made and fixed - because the fast, old code was written in C/C++ with no net. The structural defence, happening now: rewriting the risky parts in memory-safe languages (Rust in the Linux kernel, Android, Firefox) so the whole bug class disappears by construction - the strongest kind of fix (remove the possibility, not patch each instance). She is learning the old machine AND watching the field fix it. Boundary Question: 'Instead of finding memory bugs one by one forever, how would you make a whole class of them impossible?' (a safe language - the fix she just named)."),
    check("CS8-C", "Computing 8 checkpoint", ["compiled-vs-interpreted", "pointers-and-addresses", "buffers-and-bounds", "why-memory-safety"], count=10),
    teach("CS8-T", "Explain to Abid, with the row-of-boxes picture, what a buffer overflow is and why it is dangerous, then say why languages like Python and Rust were invented. Say it out loud first, then write it. 5-7 sentences."),
  ],
  read={"url": "https://en.wikipedia.org/wiki/Memory_safety", "title": "Read: memory safety - the idea behind a whole category of security"})

PROJ1 = module("PROJ1", "Project 1: build something of your own, and write it up like it matters", "Project",
  "Everything until now had a next step waiting. A project does not: you choose it, plan it, build it over days, get stuck and unstuck yourself, and write it up so a stranger understands what you made and why. This is the thing universities and teams actually look at - and the first time the whole school becomes yours to direct.",
  "the world", "A finished project of her own, on her GitHub and her logbook, with a README and a write-up a stranger can follow - the first real entry in the portfolio that MILESTONES is built around.",
  [
    lesson("PROJ1-L1", "Choose and scope: what is worth building, and small enough to finish",
      ["List three project ideas that use what she has (Pi, Python, web, the Companion, a sensor) and pick one", "Scope it to a week: what is the smallest version that works, and what is extra", "Write a one-paragraph plan and a short task list"],
      FROM_ZERO + LAB + "The hardest and most important skill: choosing. Candidates from her own tools - a Companion improvement, a home sensor that posts to the noticeboard (HW1 + WEB1), a small security tool (a log-watcher, a password-strength checker), a CTF write-up collection site. She picks one she cares about. Scoping: the smallest version that actually works (the 'minimum' - LV4), with extras listed separately so she ships something. The plan and task list in her repo. The tutor advises and questions but does not choose for her. Check: her one-paragraph plan and the smallest-working-version line."),
    lesson("PROJ1-L2", "Build it: day by day, with git, stuck and unstuck on her own",
      ["Work in small commits, each a working step (CS5), and keep a build log", "Apply the five questions and the search skills (LV3) when stuck, before asking", "Test as she goes, including the bad inputs (the Boundary Question habit)"],
      FROM_ZERO + LAB + "This is several sittings, not one. She builds in small commits with real messages; keeps a build log in the repo (what she did, what broke, how she fixed it - the write-up writes itself). When stuck: the five questions (LV4), search (LV3), the docs - then the tutor, with a four-part question (LV3). She tests her own bad inputs (every module's Boundary Question, now a reflex). The tutor's job here is lighter: unblock, not lead. The step completes when the smallest version works. Check: she shows three commits and one bug she fixed herself."),
    lesson("PROJ1-L3", "Finish and polish: make it safe, make it clear",
      ["Run her own checklist on it (input checks, no secrets in the repo, errors handled - WEB2/DEF1)", "Write the README for a stranger (CS5) and clean up the code (names, small functions)", "Record the honest limits: what it does not do, what she would add next"],
      FROM_ZERO + LAB + "The difference between a school exercise and real work is finishing. Her security checklist on her own project (the WEB2/DEF1 habits); no secrets committed (CS5-L2); errors handled kindly. The README a stranger can follow (CS5-L4). Honest limits written down - the mark of someone who understands their own work. If the project touches the network or other people's data, she states the privacy and safety rules she followed. Check: the README answers who/what/how-to-run; the limits are written."),
    lesson("PROJ1-L4", "Write it up and ship it: the portfolio piece",
      ["Write the project up as a story (the problem, the plan, the hard part, the result, what she learned) for her logbook and site", "Push it public on GitHub with the README and the write-up", "Explain who this is for and why a written project beats a certificate (CS1B-R1, closing the loop)"],
      FROM_ZERO + LAB + "The write-up is the credential. The shape: the problem she chose, how she planned it, the hardest moment and how she got through, the result (with a picture or a demo), what she learned and would do differently. Public on GitHub; linked in her logbook and ready for the site (CS9, later). The loop from CS1B-R1 closes: she now HAS the dated, public, real-work proof that beats a certificate - the first piece of the MILESTONES portfolio. Abid gets the link; this is the gift to 'the world'. Check: her write-up has all five parts; it is public and findable."),
    teach("PROJ1-T", "Explain to Abid what you built, why you chose it, the hardest part and how you got past it, and what you would do next - as if you were showing it to someone who might one day give you a place to study or work. Say it out loud first, then write it. 6-8 sentences."),
  ])

MODULES = [M15, SS5, CS7, CS8, PROJ1]
